"""Private reference review; only the report is written to the agent workspace."""
import json
import os
from pathlib import Path

REPO = Path(os.environ.get("BENCH_REPO_ROOT", "/app/repo"))
APP = Path(os.environ.get("BENCH_APP_ROOT", "/app"))
REPORT = json.loads("{\"schema_version\":2,\"reviews\":[{\"candidate\":\"cedar\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"batches\":[[1,2,3],[1,2]]},\"expected\":{\"means\":[2,1.5]}},{\"input\":{\"batches\":[[-2,-1],[0]]},\"expected\":{\"means\":[-1.5,0]}},{\"input\":{\"batches\":[[2,4],[3,8]]},\"expected\":{\"means\":[3,5.5]}},{\"input\":{\"batches\":[[],[1]]},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"batches\":[]},\"expected\":{\"means\":[]}},{\"input\":{\"batches\":[[1000000,-1000000],[1000000,-999999]]},\"expected\":{\"means\":[0,0.5]}},{\"input\":{\"batches\":[[1,0.5]]},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"batches\":[[true,2]]},\"expected\":{\"error\":\"ValueError\"}}]},{\"candidate\":\"maple\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/maple/stats.py\",\"line\":4},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"batches\":[[1,2,3],[1,2]]},\"expected\":{\"means\":[2,1.5]}},{\"input\":{\"batches\":[[-2,-1],[0]]},\"expected\":{\"means\":[-1.5,0]}},{\"input\":{\"batches\":[[2,4],[3,8]]},\"expected\":{\"means\":[3,5.5]}},{\"input\":{\"batches\":[[],[1]]},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"batches\":[]},\"expected\":{\"means\":[]}},{\"input\":{\"batches\":[[1000000,-1000000],[1000000,-999999]]},\"expected\":{\"means\":[0,0.5]}},{\"input\":{\"batches\":[[1,0.5]]},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"batches\":[[true,2]]},\"expected\":{\"error\":\"ValueError\"}}]},{\"candidate\":\"birch\",\"decision\":\"accept\",\"location\":null,\"behavior\":null,\"cases\":[{\"input\":{\"batches\":[[1,2,3],[1,2]]},\"expected\":{\"means\":[2,1.5]}},{\"input\":{\"batches\":[[-2,-1],[0]]},\"expected\":{\"means\":[-1.5,0]}},{\"input\":{\"batches\":[[2,4],[3,8]]},\"expected\":{\"means\":[3,5.5]}},{\"input\":{\"batches\":[[],[1]]},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"batches\":[]},\"expected\":{\"means\":[]}},{\"input\":{\"batches\":[[1000000,-1000000],[1000000,-999999]]},\"expected\":{\"means\":[0,0.5]}},{\"input\":{\"batches\":[[1,0.5]]},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"batches\":[[true,2]]},\"expected\":{\"error\":\"ValueError\"}}]},{\"candidate\":\"willow\",\"decision\":\"reject\",\"location\":{\"path\":\"candidates/willow/stats.py\",\"line\":4},\"behavior\":\"The candidate violates the documented public behavior on the supplied executable counterexample.\",\"cases\":[{\"input\":{\"batches\":[[1,2,3],[1,2]]},\"expected\":{\"means\":[2,1.5]}},{\"input\":{\"batches\":[[-2,-1],[0]]},\"expected\":{\"means\":[-1.5,0]}},{\"input\":{\"batches\":[[2,4],[3,8]]},\"expected\":{\"means\":[3,5.5]}},{\"input\":{\"batches\":[[],[1]]},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"batches\":[]},\"expected\":{\"means\":[]}},{\"input\":{\"batches\":[[1000000,-1000000],[1000000,-999999]]},\"expected\":{\"means\":[0,0.5]}},{\"input\":{\"batches\":[[1,0.5]]},\"expected\":{\"error\":\"ValueError\"}},{\"input\":{\"batches\":[[true,2]]},\"expected\":{\"error\":\"ValueError\"}}]}]}")

def main():
    candidates = json.loads((REPO / "candidates.json").read_text())["candidates"]
    assert set(candidates) == {row["candidate"] for row in REPORT["reviews"]}
    APP.mkdir(parents=True, exist_ok=True)
    (APP / "review.json").write_text(json.dumps(REPORT, ensure_ascii=False, allow_nan=False, indent=2) + "\n", encoding="utf-8")

if __name__ == "__main__":
    main()

